<?php
require __DIR__.'/../config/koneksi.php';require_admin();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$q=$pdo->prepare('SELECT t.*,u.nama kasir FROM transaksi t LEFT JOIN users u ON u.id=t.user_id WHERE DATE(t.tanggal) BETWEEN ? AND ? ORDER BY t.tanggal DESC');$q->execute([$from,$to]);$rows=$q->fetchAll();$sum=$pdo->prepare('SELECT COALESCE(SUM(total),0) omzet,COALESCE(SUM(keuntungan),0) untung,COUNT(*) jumlah FROM transaksi WHERE DATE(tanggal) BETWEEN ? AND ?');$sum->execute([$from,$to]);$s=$sum->fetch();$modal=(float)$s['omzet']-(float)$s['untung'];
if(isset($_GET['export'])&&$_GET['export']==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="laporan-penjualan.csv"');$out=fopen('php://output','w');fputcsv($out,['Kode Transaksi','Tanggal','Kasir','Omzet','Modal','Keuntungan']);foreach($rows as $r)fputcsv($out,[$r['kode_transaksi'],$r['tanggal'],$r['kasir'],$r['total'],$r['total']-$r['keuntungan'],$r['keuntungan']]);fclose($out);exit;}
page_start('Laporan Penjualan');?>
<div class="panel-card mb-3"><form class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label">Dari tanggal</label><input class="form-control" type="date" name="from" required value="<?=e($from)?>"></div><div class="col-md-4"><label class="form-label">Sampai tanggal</label><input class="form-control" type="date" name="to" required value="<?=e($to)?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Tampilkan</button></div><div class="col-md-2"><a class="btn btn-outline-primary w-100" href="?from=<?=e($from)?>&to=<?=e($to)?>&export=csv">Ekspor CSV</a></div></form></div><div class="row g-3 mb-3"><div class="col-md-4"><div class="stat-card"><span>Total Omzet</span><strong class="money"><?=rupiah($s['omzet'])?></strong></div></div><div class="col-md-4"><div class="stat-card"><span>Estimasi Modal</span><strong class="money"><?=rupiah($modal)?></strong></div></div><div class="col-md-4"><div class="stat-card"><span>Keuntungan</span><strong class="money"><?=rupiah($s['untung'])?></strong><small><?=$s['jumlah']?> transaksi</small></div></div></div><div class="panel-card"><div class="panel-heading"><h3>Detail Penjualan</h3><button class="btn btn-outline-secondary btn-sm" onclick="window.print()">Cetak Laporan</button></div><div class="table-responsive"><table class="table modern-table"><thead><tr><th>Kode</th><th>Tanggal</th><th>Kasir</th><th>Omzet</th><th>Modal</th><th>Untung</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['kode_transaksi'])?></td><td><?=e($r['tanggal'])?></td><td><?=e($r['kasir']??'-')?></td><td><?=rupiah($r['total'])?></td><td><?=rupiah($r['total']-$r['keuntungan'])?></td><td><?=rupiah($r['keuntungan'])?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="text-center muted">Tidak ada transaksi dalam periode ini.</td></tr><?php endif; ?></tbody></table></div></div><?php page_end(); ?>
